  "sets": {
    "raw_materials": ["A", "B"],
    "products": ["Type I", "Type II"],
    "purchasable_raw_materials": ["A"],
    "purchase_blocks": {
      "A": [
        {"block_id": 1, "upper_bound": 500, "unit_cost": 10000},
        {"block_id": 2, "upper_bound": 500, "unit_cost": 8000},
        {"block_id": 3, "upper_bound": 500, "unit_cost": 6000}
      ]
    }
  },
  "planning_horizon": {
    "horizon": ["single_period"]
  },
  "parameters": {
    "initial_inventory": {
      "A": 500,
      "B": 1000
    },
    "selling_price": {
      "Type I": 4800,
      "Type II": 5600
    },
    "minimum_share": {
      "Type I": 0.5,
      "Type II": 0.6
    },
    "distinguished_crude": "A",
    "block_unit_cost": {
      "A": {
        "1": 10000,
        "2": 8000,
        "3": 6000
      }
    },
    "block_capacity": {
      "A": {
        "1": 500,
        "2": 500,
        "3": 500
      }
    },
    "purchase_cap": {
      "A": 1500
    },
    "demand_upper_bound": {}
  },
  "decision_scope": {
    "procurement": "Choose how much crude oil A to buy from each price block.",
    "blending": "Choose how much crude oil A and crude oil B are blended into Type I and Type II gasoline.",
    "production": "Choose the output quantities of Type I and Type II gasoline."
  }
}
